mapper.insert:
INSERT INTO VERIFICATIONCODE (
    VERIFICATION_NO,
    INPUT_DATE,
    USER_NO
)
VALUES (
    #{verificationNo},
    SYSDATE,
    #{userNo, jdbcType=VARCHAR}
