mapper.select:
SELECT COUNT(*)
FROM (
    SELECT verification_no
    FROM VERIFICATIONCODE
    WHERE user_no = #{userNo}
      AND input_date >= SYSDATE - (10 / 1440)
    ORDER BY input_date DESC
)
WHERE ROWNUM = 1
  AND verification_no = #{verificationNo}
